questionvariables.text:
/* Design: constraints from a resource table (one row per resource), plus the objective and a plan check. Source: adapted from SMP Book 5 (Metric), Chapter 8, Section 2.3, Example 2. Categories yes 3, breaks (a) 2, breaks (b) 3, both 2. Radio order per entry (correct never first). */
/* lincan(q): canonical form of a linear inequality in x and y: [strict?, [a, b, c]] meaning a*x + b*y + c (< or <=) 0 */
lincan(q) := block([r, d, s], r: op(q), d: expand(lhs(q) - rhs(q)),
    if r = ">" or r = ">=" then d: -d,
    s: is(r = "<" or r = ">"),
    [s, map(lambda([t], float(t)), [coeff(d, x), coeff(d, y), subst([x = 0, y = 0], d)])]);
lpar(u, v) := is(abs(u[1]*v[2] - u[2]*v[1]) + abs(u[1]*v[3] - u[3]*v[1]) + abs(u[2]*v[3] - u[3]*v[2]) < 1/10^9 * (abs(u[1]) + abs(u[2]) + abs(u[3])) * (abs(v[1]) + abs(v[2]) + abs(v[3])));
ldot(u, v) := u[1]*v[1] + u[2]*v[2] + u[3]*v[3];
/* lcls(L, T): "same" region; "dir" same boundary, other side, same strictness; "strict" same side, other strictness; "both"; "other" */
lcls(L, T) := block([l: lincan(L), t: lincan(T)],
    if not lpar(l[2], t[2]) then "other"
    elseif ldot(l[2], t[2]) > 0 then (if l[1] = t[1] then "same" else "strict")
    elseif l[1] = t[1] then "dir" else "both");
/* the validator: an inequality in x and y, linear */
validate_ineq(ex) := block([e: ev(ex, simp), d],
    if atom(e) or not member(op(e), ["<", "<=", ">", ">="]) then
        "Type an inequality using <, <=, > or >=, for example 2*x+3*y<=60. An equation with = is not an inequality."
    elseif listofvars(e) = [] or not every(lambda([v], member(v, [x, y])), listofvars(e)) then "Use only the letters x and y."
    else (d: ev(expand(lhs(e) - rhs(e)), simp),
          if not ev(polynomialp(d, [x, y]), simp) then
              "This inequality should be linear: only numbers times x and y, added or subtracted."
          elseif ev(hipow(d, x), simp) > 1 or ev(hipow(d, y), simp) > 1 or not freeof(x, ev(coeff(d, y), simp)) then
              "This inequality should be linear: no powers or products of x and y." else ""));
/* mkineq([a, b, rel, c]): the inequality a*x + b*y rel c */
mkineq(L) := if L[3] = "<=" then L[1]*x + L[2]*y <= L[4] elseif L[3] = "<" then L[1]*x + L[2]*y < L[4]
    elseif L[3] = ">=" then L[1]*x + L[2]*y >= L[4] else L[1]*x + L[2]*y > L[4];
Q12L: [["A candle maker in Kisumu makes boxes of plain candles and boxes of scented candles.","boxes of plain candles","boxes of scented candles",["Wax (kg)",7,1,125],["Time (hours)",7,4,165],350,200,[4,14],["n2","yes","nb","n1"],["wax","time"]],
["A beadwork group in Kajiado makes necklaces and bracelets.","necklaces","bracelets",["Beads (hundreds)",5,9,148],["Time (hours)",1,6,65],80,20,[6,10],["yes","nb","n1","n2"],["beads","time"]],
["A carpenter in Eldoret makes stools and benches.","stools","benches",["Timber (metres)",8,3,124],["Time (hours)",8,7,167],500,400,[15,4],["n2","yes","n1","nb"],["timber","time"]],
["A tailor in Kitale makes school skirts and school blazers.","skirts","blazers",["Cloth (metres)",7,5,109],["Sewing (hours)",9,7,145],650,550,[13,6],["n1","nb","yes","n2"],["cloth","sewing"]],
["A jua kali workshop in Kamukunji makes wheelbarrows and metal trunks.","wheelbarrows","metal trunks",["Steel sheet (square metres)",9,4,186],["Welding (hours)",8,9,219],600,2000,[15,1],["n2","nb","yes","n1"],["steel sheet","welding"]],
["A women's group in Kitui weaves kiondo baskets and sisal mats.","baskets","mats",["Sisal (kg)",8,9,203],["Weaving (hours)",2,7,99],1000,350,[6,13],["n1","n2","yes","nb"],["sisal","weaving"]],
["A mushroom grower in Kiambu fills bags of oyster mushrooms and trays of button mushrooms.","bags","trays",["Compost (kg)",7,3,123],["Labour (minutes)",9,5,176],30,160,[16,6],["nb","n2","n1","yes"],["compost","labour"]],
["A printing shop in Kisii prints packs of posters and packs of booklets.","packs of posters","packs of booklets",["Paper (reams)",8,7,168],["Machine time (minutes)",5,9,155],950,850,[7,7],["nb","n1","n2","yes"],["paper","machine time"]],
["A tree nursery in Murang'a raises trays of avocado seedlings and trays of macadamia seedlings.","avocado trays","macadamia trays",["Potting soil (kg)",7,2,77],["Water (litres per day)",5,9,133],400,600,[5,14],["yes","nb","n2","n1"],["potting soil","water"]],
["A honey processor in Baringo packs jars and buckets of honey.","jars","buckets",["Honey (kg)",1,7,72],["Labelling (minutes)",1,9,87],300,150,[11,9],["yes","n1","n2","nb"],["honey","labelling"]]];
ix: 1+rand(10);
E: Q12L[ix];
r1: E[4][1]; a1: E[4][2]; b1: E[4][3]; c1: E[4][4];
r2: E[5][1]; a2: E[5][2]; b2: E[5][3]; c2: E[5][4]; rsh: E[10];
p1: E[6]; p2: E[7]; x0: E[8][1]; y0: E[8][2];
ta1: a1*x+b1*y<=c1; ta2: a2*x+b2*y<=c2; ta3: p1*x+p2*y;
col1: a1*x+a2*y<=c1; col2: b1*x+b2*y<=c2;
sw1: b1*x+a1*y<=c1; sw2: b2*x+a2*y<=c2;
dr1: a1*x+b1*y>=c1; dr2: a2*x+b2*y>=c2;
u1: a1*x0+b1*y0; u2: a2*x0+b2*y0;
keyp: if u1<=c1 and u2<=c2 then "yes" elseif u1>c1 and u2>c2 then "nb" elseif u1>c1 then "n1" else "n2";
optd(k) := if k="yes" then "Yes: the plan satisfies both conditions." elseif k="n1" then sconcat("No: it needs more than they have of the first resource (", rsh[1], ").")
  elseif k="n2" then sconcat("No: it needs more than they have of the second resource (", rsh[2], ").") else "No: it needs more than they have of both resources.";
opts: makelist([E[9][j], is(E[9][j]=keyp), optd(E[9][j])], j, 1, 4);
wrongkey: E[9][1+mod(sublist_indices(E[9], lambda([t], t=keyp))[1], 4)];
lt1: if u1<=c1 then "at most" else "more than"; lt2: if u2<=c2 then "at most" else "more than";
validate_obj(ex) := if not atom(ex) and member(op(ex), ["=", "<", "<=", ">", ">="]) then "Type only the expression, for example 300x+800y." else "";
